exercises.solution:
rows = [
    {"title": "tea", "amount": 30},
    {"title": "book", "amount": 250},
]

def total(rows):
    return sum(row["amount"] for row in rows)

def biggest(rows):
    return max(rows, key=lambda row: row["amount"])["title"]

print(total(rows))
print(biggest(rows))
